def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 19:
        return 'C'
    if n == 19:
        return 'D'
    if n == 20:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_def = sum(1 for a in my if a == 'D')
    my_c = n - my_def
    op_def = sum(1 for a in op if a == 'D')
    last_me, last_op = history[-1]

    recent_len = min(5, n)
    recent_op = op[-recent_len:]
    recent_op_def = sum(1 for a in recent_op if a == 'D')

    if recent_op_def > 0:
        if last_op == 'D':
            if op_def == 1 and n > 5:
                return 'C'
            if my_def > op_def + 2:
                return 'C'
            return 'D'
        else:
            return 'C'
    else:
        if my_def < my_c:
            return 'D'
        else:
            return 'C'
